local function dec(s)
 local b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
 s=s:gsub("[^"..b.."]","")
 local t={}
 for i=1,#s,4 do
  local n1=b:find(s:sub(i,i),1,true)-1;local n2=b:find(s:sub(i+1,i+1),1,true)-1;local n3=b:find(s:sub(i+2,i+2),1,true);local n4=b:find(s:sub(i+3,i+3),1,true)
  n3=(n3 and n3-1 or 0);n4=(n4 and n4-1 or 0)
  local n=n1*262144+n2*4096+n3*64+n4
  t[#t+1]=string.char(math.floor(n/65536)%256,math.floor(n/256)%256,n%256)
 end
 return table.concat(t)
end
